                guard zoomWindowNumber == editorWindowNumber else { return false }
                withAnimation(.easeInOut(duration: 0.15)) {
                    if keyCode == Self.zoomResetKey {
                        zoom = 1
                    } else if Self.zoomInKeys.contains(keyCode) {
                        zoom = min(zoom * 1.25, 3)
