import Foundation
import Testing
@testable import ZoiaCanvas

/// The pick-up-and-move gesture's model half: unplugging the newest
/// cable from an input hands back its far end with strength intact,
/// and the edited flag tracks everything that reaches the .bin.
@Suite @MainActor struct CableReconnectTests {
    private func catalog() throws -> ModuleCatalog {
        try ModuleCatalog.loadBundled()
    }

    private func port(_ module: CanvasModule, in document: PatchDocument,
                      output: Bool) throws -> PortRef {
        let block = try #require(module.activeBlocks(in: document.catalog)
            .first { $0.type.isOutput == output })
        return PortRef(module: module.id,
                       blockPosition: block.position ?? 0, type: block.type)
    }

    @Test func unplugReturnsNewestCableAndKeepsStrength() throws {
        let document = PatchDocument(catalog: try catalog())
        let a = try #require(document.addModule(typeID: 1, at: .zero))
        let b = try #require(document.addModule(typeID: 1, at: .zero))
        let sink = try #require(document.addModule(typeID: 2, at: .zero))
        let dest = try port(sink, in: document, output: false)
        document.connect(from: try port(a, in: document, output: true), to: dest)
        document.connect(from: try port(b, in: document, output: true), to: dest,
                         strengthRaw: 5000)

        let picked = try #require(document.unplugConnection(into: dest))
        #expect(picked.source.module == b.id, "newest cable comes off first")
        #expect(picked.strengthRaw == 5000, "strength travels with the plug")
        #expect(document.connections.count == 1)
        #expect(document.connections[0].sourceModule == a.id)

        // Re-plugging the picked end elsewhere is a plain connect.
        let ruling = document.connect(from: picked.source, to: dest,
                                      strengthRaw: picked.strengthRaw)
        #expect(ruling == .allowed)
    }

    @Test func unplugEmptyOrOutputPortReturnsNil() throws {
        let document = PatchDocument(catalog: try catalog())
        let source = try #require(document.addModule(typeID: 1, at: .zero))
        let sink = try #require(document.addModule(typeID: 2, at: .zero))
        #expect(document.unplugConnection(
            into: try port(sink, in: document, output: false)) == nil)
        #expect(document.unplugConnection(
            into: try port(source, in: document, output: true)) == nil)
    }

    @Test func editedFlagTracksSaveWorthyChanges() throws {
        let document = PatchDocument(catalog: try catalog())
        #expect(!document.isEdited, "a fresh document is clean")

        let module = try #require(document.addModule(typeID: 0, at: .zero))
        #expect(document.isEdited, "structure changes mark it")
        document.markSaved()
        #expect(!document.isEdited)

        document.setGridPosition(module.id, to: 8)
        #expect(document.isEdited, "grid slots reach the .bin")
        document.markSaved()

        document.setCustomName(module.id, to: "flt")
        #expect(document.isEdited, "names reach the .bin")
        document.markSaved()

        document.setColorID(module.id, to: 3)
        #expect(document.isEdited, "colors reach the .bin")
        document.markSaved()

        document.renamePage(0, to: "main")
        #expect(document.isEdited, "page names reach the .bin")
    }

    @Test func openedPatchStartsClean() throws {
        let bundle = Bundle(for: CorpusHook.self)
        let root = try #require(bundle.resourceURL?.appendingPathComponent("Corpus"))
        let patch = try ZoiaPatchBinary.decode(try Data(contentsOf:
            root.appendingPathComponent("Factory/023_zoia_Snowfall.bin")))
        let document = PatchDocument(patch: patch, catalog: try catalog())
        #expect(!document.isEdited, "opening a file is not an edit")
    }
}

private final class CorpusHook {}

import Foundation
import Testing
@testable import ZoiaCanvas

/// One-shot generator (removed after running): writes AnimationDemo.bin
/// to the project root — a patch with every animation live at once.
@Suite @MainActor struct AnimationDemoGenerator {
    private func optionByte(_ spec: ModuleSpec, key: String, value: String) -> UInt8? {
        guard let optIndex = spec.options.firstIndex(where: { $0.key == key }),
              let valIndex = spec.options[optIndex].values.firstIndex(where: {
                  $0.description == value
              }) else { return nil }
        _ = optIndex
        return UInt8(valIndex)
    }

    private func optionIndex(_ spec: ModuleSpec, key: String) -> Int? {
        spec.options.firstIndex { $0.key == key }
    }

    @Test func generate() throws {
        let catalog = try ModuleCatalog.loadBundled()
        let document = PatchDocument(catalog: catalog)
        document.patchName = "Anim Demo"

        func add(_ typeID: Int, _ name: String, x: CGFloat, y: CGFloat) throws -> CanvasModule {
            let m = try #require(document.addModule(
                typeID: typeID, at: CGPoint(x: x, y: y)))
            document.setCustomName(m.id, to: name)
            return m
        }
        // Blocks resolved by role from the live layout, not guessed.
        func blk(_ m: CanvasModule, output: Bool, kind: String? = nil,
                 minPos: Int = 0, skip: Int = 0) throws -> PortRef {
            let blocks = m.activeBlocks(in: catalog).enumerated().filter {
                $0.element.type.isOutput == output
                    && ($0.element.position ?? $0.offset) >= minPos
                    && (kind == nil || $0.element.type.isAudio == (kind == "audio"))
            }
            let pick = try #require(blocks.dropFirst(skip).first)
            return PortRef(module: m.id,
                           blockPosition: pick.element.position ?? pick.offset,
                           type: pick.element.type)
        }
        func setOpt(_ m: CanvasModule, _ key: String, _ value: String) throws {
            let spec = try #require(catalog[m.typeID])
            let idx = try #require(optionIndex(spec, key: key))
            let byte = try #require(optionByte(spec, key: key, value: value))
            document.setOption(m.id, optionIndex: idx, byte: byte)
        }
        func setParam(_ m: CanvasModule, position: Int, _ fraction: Double) throws {
            let fresh = try #require(document.module(m.id))
            let blocks = document.paramBlocks(of: fresh)
            let idx = try #require(blocks.enumerated().first {
                ($0.element.position ?? $0.offset) == position
            }?.offset)
            document.setParam(m.id, paramIndex: idx, fraction: fraction)
        }

        let clock = try add(5, "CLOCK", x: 60, y: 60)          // square LFO
        try setOpt(clock, "waveform", "square")
        let sweep = try add(5, "SWEEP", x: 60, y: 220)         // sine LFO
        try setOpt(sweep, "waveform", "sine")
        let seq = try add(4, "SEQ", x: 320, y: 60)
        try setOpt(seq, "number_of_steps", "4")
        let osc = try add(14, "OSC", x: 580, y: 60)
        let filt = try add(0, "FILTER", x: 840, y: 60)
        let vca = try add(7, "VCA", x: 1100, y: 60)
        let pan = try add(57, "PAN", x: 1360, y: 60)
        let out = try add(2, "OUT", x: 1620, y: 60)

        func wire(_ from: PortRef, _ to: PortRef) throws {
            let ruling = document.connect(from: from, to: to)
            try #require(ruling == .allowed || ruling == .allowedTypeMismatch)
        }
        // Gate pulses: square LFO clocks the sequencer and chops the VCA.
        try wire(try blk(clock, output: true), try blk(seq, output: false, minPos: 32))
        try wire(try blk(clock, output: true), try blk(vca, output: false, kind: "cv"))
        // Modulation overlay: sequencer steps the pitch, sine sweeps
        // the filter and the pan.
        try wire(try blk(seq, output: true), try blk(osc, output: false, kind: "cv"))
        try wire(try blk(sweep, output: true), try blk(filt, output: false, kind: "cv"))
        try wire(try blk(sweep, output: true), try blk(pan, output: false, kind: "cv"))
        // Audio waveform + module glow: osc → filter → vca → pan → out.
        try wire(try blk(osc, output: true, kind: "audio"),
                 try blk(filt, output: false, kind: "audio"))
        try wire(try blk(filt, output: true, kind: "audio"),
                 try blk(vca, output: false, kind: "audio"))
        try wire(try blk(vca, output: true, kind: "audio"),
                 try blk(pan, output: false, kind: "audio"))
        try wire(try blk(pan, output: true, kind: "audio"),
                 try blk(out, output: false, kind: "audio"))
        try wire(try blk(pan, output: true, kind: "audio", skip: 1),
                 try blk(out, output: false, kind: "audio", skip: 1))

        // ~1.1 Hz clock, ~0.3 Hz sweep (cv dial is exponential
        // 0.05…25 Hz); sequencer steps land around 220–560 Hz on the
        // 27.5×2^(10cv) pitch curve.
        try setParam(clock, position: 0, 0.5)
        try setParam(sweep, position: 0, 0.28)
