import AppKit

// ZOIA Canvas app icon: the pedal's 8x5 LED grid on a dark squircle,
// a few buttons lit in module category colors, one glowing cable
// sweeping between two of them.

func color(_ hex: UInt32, _ alpha: CGFloat = 1) -> NSColor {
    NSColor(srgbRed: CGFloat((hex >> 16) & 0xFF) / 255,
            green: CGFloat((hex >> 8) & 0xFF) / 255,
            blue: CGFloat(hex & 0xFF) / 255, alpha: alpha)
}

// (col, row, color) — row 0 is the top row.
let lit: [(Int, Int, NSColor)] = [
    (1, 3, color(0x4A90D9)),   // blue: cable start
    (6, 1, color(0xE8964A)),   // orange: cable end
    (3, 0, color(0x50B860)),
    (5, 3, color(0xD050C0)),
    (2, 1, color(0x4AC8C8)),
    (6, 4, color(0xE8C84A)),
    (0, 0, color(0xE05545)),
]

func drawIcon(into rect: NSRect) {
    let S = rect.width / 1024
    func pt(_ x: CGFloat, _ y: CGFloat) -> NSPoint { NSPoint(x: x * S, y: y * S) }

    // Squircle plate, Apple-grid margins.
    let plate = NSRect(x: 100 * S, y: 100 * S, width: 824 * S, height: 824 * S)
    let squircle = NSBezierPath(roundedRect: plate, xRadius: 185 * S, yRadius: 185 * S)
    NSGradient(colors: [color(0x2A2D35), color(0x16171B)])!
        .draw(in: squircle, angle: -90)

    // Grid geometry: 8 x 5 buttons, 60pt buttons on 84pt pitch.
    let button: CGFloat = 60, pitch: CGFloat = 84
    let gridW = 7 * pitch + button
    let gridH = 4 * pitch + button
    let x0 = (1024 - gridW) / 2
    let y0 = (1024 - gridH) / 2
    func cell(_ col: Int, _ row: Int) -> NSRect {
        NSRect(x: (x0 + CGFloat(col) * pitch) * S,
               y: (y0 + CGFloat(4 - row) * pitch) * S,
               width: button * S, height: button * S)
    }
    func center(_ col: Int, _ row: Int) -> NSPoint {
        let r = cell(col, row)
        return NSPoint(x: r.midX, y: r.midY)
    }

    // Dim buttons.
    for row in 0..<5 {
        for col in 0..<8 {
            let path = NSBezierPath(roundedRect: cell(col, row),
                                    xRadius: 13 * S, yRadius: 13 * S)
            color(0x34363E).setFill()
            path.fill()
        }
    }

    // Lit buttons: radial glow beneath, bright rounded button on top.
    for (col, row, tint) in lit {
        let c = center(col, row)
        let glow = NSGradient(colors: [tint.withAlphaComponent(0.55),
                                       tint.withAlphaComponent(0)])!
        let glowRadius = 110 * S
        glow.draw(in: NSRect(x: c.x - glowRadius, y: c.y - glowRadius,
                             width: glowRadius * 2, height: glowRadius * 2),
                  relativeCenterPosition: .zero)
        let path = NSBezierPath(roundedRect: cell(col, row),
                                xRadius: 13 * S, yRadius: 13 * S)
        tint.setFill()
        path.fill()
        // Soft top-light on the lit key.
        NSGradient(colors: [NSColor.white.withAlphaComponent(0.35),
                            NSColor.white.withAlphaComponent(0)])!
            .draw(in: path, angle: -90)
    }

    // The cable: blue button up and over to the orange one.
    let from = center(1, 3), to = center(6, 1)
    let cable = NSBezierPath()
    cable.move(to: from)
    cable.curve(to: to,
                controlPoint1: pt(300, 900),
                controlPoint2: pt(730, 830))
    cable.lineCapStyle = .round
    let cableColor = color(0x5AA8E8)
    cableColor.withAlphaComponent(0.28).setStroke()
    cable.lineWidth = 46 * S
    cable.stroke()
    cableColor.setStroke()
    cable.lineWidth = 20 * S
    cable.stroke()
    color(0xC8E4FA).setStroke()
    cable.lineWidth = 7 * S
    cable.stroke()
}

func renderPNG(pixels: Int, to url: URL) {
    let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: pixels,
                               pixelsHigh: pixels, bitsPerSample: 8,
                               samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                               colorSpaceName: .calibratedRGB, bytesPerRow: 0,
                               bitsPerPixel: 0)!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
    NSGraphicsContext.current?.imageInterpolation = .high
    drawIcon(into: NSRect(x: 0, y: 0, width: pixels, height: pixels))
    NSGraphicsContext.restoreGraphicsState()
    try! rep.representation(using: .png, properties: [:])!.write(to: url)
}

let out = URL(fileURLWithPath: CommandLine.arguments[1])
let iconset = out.appendingPathComponent("ZoiaCanvas.iconset")
try? FileManager.default.createDirectory(at: iconset, withIntermediateDirectories: true)
let entries: [(String, Int)] = [
    ("icon_16x16.png", 16), ("icon_16x16@2x.png", 32),
    ("icon_32x32.png", 32), ("icon_32x32@2x.png", 64),
    ("icon_128x128.png", 128), ("icon_128x128@2x.png", 256),
    ("icon_256x256.png", 256), ("icon_256x256@2x.png", 512),
    ("icon_512x512.png", 512), ("icon_512x512@2x.png", 1024),
]
for (name, pixels) in entries {
    renderPNG(pixels: pixels, to: iconset.appendingPathComponent(name))
}
renderPNG(pixels: 1024, to: out.appendingPathComponent("icon-preview.png"))
print("done")

import AppKit

// ZOIA Canvas app icon: the page-preview tile from the app's page bar,
// scaled up — the pedal's 8x5 button grid with modules lighting runs
// of consecutive buttons in their colors.

func color(_ hex: UInt32, _ alpha: CGFloat = 1) -> NSColor {
    NSColor(srgbRed: CGFloat((hex >> 16) & 0xFF) / 255,
            green: CGFloat((hex >> 8) & 0xFF) / 255,
            blue: CGFloat(hex & 0xFF) / 255, alpha: alpha)
}

// Module runs, like a real page: consecutive buttons share a module's
// color; 0 is an empty button. Reads left-to-right, top row first.
let runs: [(UInt32, Int)] = [
    (0x4A90D9, 3), (0x50B860, 2), (0, 1), (0xE05545, 2),      // row 0
    (0xE8C84A, 1), (0x4AC8C8, 3), (0xD050C0, 2), (0, 2),      // row 1
    (0xE8964A, 4), (0, 1), (0x8A6FD8, 2), (0x4A90D9, 1),      // row 2
    (0x50B860, 1), (0, 2), (0x70C8E8, 3), (0xE05545, 1), (0, 1), // row 3
    (0xD8D8D8, 2), (0xE8C84A, 2), (0, 1), (0x50E0A0, 3),      // row 4
]

func drawIcon(into rect: NSRect) {
    let S = rect.width / 1024

    // Squircle plate, Apple-grid margins — the tile's light ground.
    let plate = NSRect(x: 100 * S, y: 100 * S, width: 824 * S, height: 824 * S)
    let squircle = NSBezierPath(roundedRect: plate, xRadius: 185 * S, yRadius: 185 * S)
    NSGradient(colors: [color(0xF2F3F5), color(0xD4D7DC)])!
        .draw(in: squircle, angle: -90)

    // Grid geometry: 8 x 5 buttons on a uniform pitch.
    let button: CGFloat = 76, gap: CGFloat = 18
    let pitch = button + gap
    let gridW = 8 * pitch - gap
    let gridH = 5 * pitch - gap
    let x0 = (1024 - gridW) / 2
    let y0 = (1024 - gridH) / 2
    func cell(_ col: Int, _ row: Int) -> NSRect {
        NSRect(x: (x0 + CGFloat(col) * pitch) * S,
               y: (y0 + CGFloat(4 - row) * pitch) * S,
               width: button * S, height: button * S)
    }

    // Unroll runs into 40 cells.
    var cells: [UInt32] = []
    for (hex, count) in runs { cells.append(contentsOf: Array(repeating: hex, count: count)) }
    precondition(cells.count == 40, "grid must be exactly 40 buttons, got \(cells.count)")

    for row in 0..<5 {
        for col in 0..<8 {
            let hex = cells[row * 8 + col]
            let rect = cell(col, row)
            let path = NSBezierPath(roundedRect: rect, xRadius: 16 * S, yRadius: 16 * S)
            if hex == 0 {
                color(0xC2C5CB).setFill()
                path.fill()
            } else {
                let tint = color(hex)
                // A soft halo so the lights read as lit, not printed.
                let c = NSPoint(x: rect.midX, y: rect.midY)
                let glowRadius = 86 * S
                NSGradient(colors: [tint.withAlphaComponent(0.42),
                                    tint.withAlphaComponent(0)])!
                    .draw(in: NSRect(x: c.x - glowRadius, y: c.y - glowRadius,
                                     width: glowRadius * 2, height: glowRadius * 2),
                          relativeCenterPosition: .zero)
                tint.setFill()
                path.fill()
                NSGradient(colors: [NSColor.white.withAlphaComponent(0.4),
                                    NSColor.white.withAlphaComponent(0)])!
                    .draw(in: path, angle: -90)
            }
        }
    }
}

func renderPNG(pixels: Int, to url: URL) {
    let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: pixels,
                               pixelsHigh: pixels, bitsPerSample: 8,
                               samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                               colorSpaceName: .calibratedRGB, bytesPerRow: 0,
                               bitsPerPixel: 0)!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
    NSGraphicsContext.current?.imageInterpolation = .high
    drawIcon(into: NSRect(x: 0, y: 0, width: pixels, height: pixels))
    NSGraphicsContext.restoreGraphicsState()
    try! rep.representation(using: .png, properties: [:])!.write(to: url)
}

let out = URL(fileURLWithPath: CommandLine.arguments[1])
let iconset = out.appendingPathComponent("ZoiaCanvas.iconset")
try? FileManager.default.createDirectory(at: iconset, withIntermediateDirectories: true)
let entries: [(String, Int)] = [
    ("icon_16x16.png", 16), ("icon_16x16@2x.png", 32),
    ("icon_32x32.png", 32), ("icon_32x32@2x.png", 64),
    ("icon_128x128.png", 128), ("icon_128x128@2x.png", 256),
    ("icon_256x256.png", 256), ("icon_256x256@2x.png", 512),
    ("icon_512x512.png", 512), ("icon_512x512@2x.png", 1024),
]
for (name, pixels) in entries {
    renderPNG(pixels: pixels, to: iconset.appendingPathComponent(name))
}
renderPNG(pixels: 1024, to: out.appendingPathComponent("icon-preview.png"))
print("done")
